const fs = require\('fs'\);

function createPNG\(size\) {
  // PNG header + IHDR + IDAT + IEND
  function crc32\(buf\) {
    let c = 0xFFFFFFFF;
    const table = [];
    for \(let i = 0; i < 256; i++\) {
      let k = i;
      for \(let j = 0; j < 8; j++\) k = k & 1 ? 0xEDB88320 ^ \(k >>> 1\) : k >>> 1;
      table[i] = k;
    }
    for \(let i = 0; i < buf.length; i++\) c = table[\(c ^ buf[i]\) & 0xFF] ^ \(c >>> 8\);
    return \(c ^ 0xFFFFFFFF\) >>> 0;
  }
  function chunk\(type, data\) {
    const typeB = Buffer.from\(type\);
    const len = Buffer.alloc\(4\); len.writeUInt32BE\(data.length\);
    const crcB = Buffer.alloc\(4\);
    crcB.writeUInt32BE\(crc32\(Buffer.concat\([typeB, data]\)\)\);
    return Buffer.concat\([len, typeB, data, crcB]\);
  }
  function adler32\(buf\) {
    let s1 = 1, s2 = 0;
    for \(const b of buf\) { s1 = \(s1 + b\) % 65521; s2 = \(s2 + s1\) % 65521; }
    return \(\(s2 << 16\) | s1\) >>> 0;
  }
  function deflate\(data\) {
    // No-compression deflate
    const blocks = [];
    let offset = 0;
    while \(offset < data.length\) {
      const end = Math.min\(offset + 65535, data.length\);
      const block = data.slice\(offset, end\);
      const isLast = end >= data.length ? 1 : 0;
      const hdr = Buffer.alloc\(5\);
      hdr[0] = isLast;
      hdr.writeUInt16LE\(block.length, 1\);
      hdr.writeUInt16LE\(~block.length & 0xFFFF, 3\);
      blocks.push\(hdr, block\);
      offset = end;
    }
    const adler = Buffer.alloc\(4\);
    adler.writeUInt32BE\(adler32\(data\)\);
    return Buffer.concat\([Buffer.from\([0x78, 0x01]\), ...blocks, adler]\);
  }

  // Background #1a1208, letter F in #c8820a
  const bgR = 0x1a, bgG = 0x12, bgB = 0x08;
  const fgR = 0xc8, fgG = 0x82, fgB = 0x0a;

  // Draw F shape as fraction of size
  const rows = [];
  for \(let y = 0; y < size; y++\) {
    const row = [0]; // filter byte
    const yf = y / size;
    for \(let x = 0; x < size; x++\) {
      const xf = x / size;
      // F: vertical bar 0.2-0.35x, horizontal top 0.2-0.75x at y 0.15-0.28, middle bar 0.2-0.6x at y 0.44-0.57
      const inVBar = xf >= 0.20 && xf <= 0.35 && yf >= 0.15 && yf <= 0.85;
      const inTopBar = xf >= 0.20 && xf <= 0.75 && yf >= 0.15 && yf <= 0.28;
      const inMidBar = xf >= 0.20 && xf <= 0.62 && yf >= 0.44 && yf <= 0.57;
      const inF = inVBar || inTopBar || inMidBar;
      row.push\(inF ? fgR : bgR, inF ? fgG : bgG, inF ? fgB : bgB\);
    }
    rows.push\(Buffer.from\(row\)\);
  }

  const ihdr = Buffer.alloc\(13\);
  ihdr.writeUInt32BE\(size, 0\); ihdr.writeUInt32BE\(size, 4\);
  ihdr[8] = 8; ihdr[9] = 2; // 8-bit RGB
  const sig = Buffer.from\([137,80,78,71,13,10,26,10]\);
  const idatRaw = Buffer.concat\(rows\);
  const idat = chunk\('IDAT', deflate\(idatRaw\)\);
  return Buffer.concat\([sig, chunk\('IHDR', ihdr\), idat, chunk\('IEND', Buffer.alloc\(0\)\)]\);
}

fs.mkdirSync\('./public', { recursive: true }\);
fs.writeFileSync\('./public/icon-192.png', createPNG\(192\)\);
fs.writeFileSync\('./public/icon-512.png', createPNG\(512\)\);
console.log\('Iconos generados'\);
")
